// Literal SQL seguro. Duplicar la comilla simple es lo mismo que hace
// quote_literal() en Postgres, y con standard_conforming_strings=on (por
// defecto) no hay ninguna otra secuencia de escape que valga.
const lit = (v) => (v === null || v === undefined || v === '')
  ? 'null'
  : "'" + String(v).replace(/'/g, "''") + "'";

            // Evolution cambia de forma entre versiones y n8n mete el cuerpo en
            // `body`. Esto tolera ambas cosas.
            const entrada = $input.first().json;
            const raw  = entrada.body ?? entrada;
            const dato = raw.data ?? raw;
            const clave = dato.key ?? {};

            const jid    = String(clave.remoteJid ?? dato.remoteJid ?? '');
            const esGrupo = jid.includes('@g.us') || jid.includes('broadcast');
            const telefono = jid.split('@')[0].split(':')[0].replace(/\D/g, '');

            const m = dato.message ?? {};
            const anidado = m.ephemeralMessage?.message ?? m.viewOnceMessage?.message ?? m;

            const texto =
                 anidado.conversation
              ?? anidado.extendedTextMessage?.text
              ?? anidado.imageMessage?.caption
              ?? anidado.videoMessage?.caption
              ?? anidado.buttonsResponseMessage?.selectedDisplayText
              ?? anidado.listResponseMessage?.title
              ?? (anidado.audioMessage       ? '[nota de voz]'  : null)
              ?? (anidado.imageMessage       ? '[imagen]'       : null)
              ?? (anidado.stickerMessage     ? '[sticker]'      : null)
              ?? (anidado.documentMessage    ? '[documento]'    : null)
              ?? (anidado.locationMessage    ? '[ubicación]'    : null)
              ?? (anidado.contactMessage     ? '[contacto]'     : null)
              ?? '';

            return [{ json: {
              telefono,
              texto: String(texto).slice(0, 4000),
              wa_id: clave.id ?? null,
              nombre: dato.pushName ?? null,
              de_mi: clave.fromMe === true,
              es_grupo: esGrupo,
              procesable: !esGrupo && clave.fromMe !== true && telefono.length >= 10 && String(texto).trim() !== '',
              // Para la bitácora cruda: si Evolution cambia el formato, aquí queda
              // el payload original para comparar.
              evento_sql: lit(JSON.stringify(raw).slice(0, 60000)),
              telefono_sql: lit(telefono),
              texto_sql: lit(String(texto).slice(0, 4000)),
              wa_id_sql: lit(clave.id ?? null),
              nombre_sql: lit(dato.pushName ?? null),
            } }];

