const lead = $input.first().json;
const cfg  = lead.cfg;
const entrante = $('Normalizar').first().json;

const contexto = {
  negocio: lead.negocio, contacto: lead.nombre, rubro: lead.rubro,
  ciudad: lead.ciudad, sitio_web: lead.sitio_web || '(no tiene página)',
  observacion: lead.observacion, estado_actual: lead.estado,
  mensajes_previos_enviados: lead.toques,
};

// El historial ya viene en formato de mensajes de la API. El último
// mensaje del lead ya está incluido porque se guardó antes de llegar aquí.
const historial = Array.isArray(lead.historial) ? lead.historial : [];
const mensajes = historial.length ? historial
                                  : [{ role: 'user', content: entrante.texto }];

// El contexto del negocio va como primer turno para no romper el
// prefijo cacheado del system.
mensajes.unshift({
  role: 'user',
  content: 'Ficha del lead con el que estás hablando:'
         + String.fromCharCode(10) + JSON.stringify(contexto, null, 2),
});
if (mensajes[1] && mensajes[1].role === 'user') {
  // Dos turnos 'user' seguidos son válidos: la API los une.
}

const peticion = {
  model: cfg.modelo || 'claude-opus-5',
  max_tokens: 8000,
  output_config: {
    effort: cfg.esfuerzo_conversacion || 'medium',
    format: { type: 'json_schema', schema: {"type": "object", "properties": {"intencion": {"type": "string", "enum": ["baja", "interesado", "pregunta", "no_interesado", "no_es_el_indicado", "ruido"]}, "temperatura": {"type": "integer", "minimum": 1, "maximum": 5}, "requiere_humano": {"type": "boolean"}, "respuesta": {"type": "string", "description": "Lo que se le envía al lead. Vacío solo si no hay que responder."}, "nota_interna": {"type": "string", "description": "Una línea para José. No se le envía al lead."}}, "required": ["intencion", "temperatura", "requiere_humano", "respuesta", "nota_interna"], "additionalProperties": false} },
  },
  system: [{
    type: 'text',
    text: cfg.ficha_comercial + String.fromCharCode(10, 10) + cfg.prompt_conversacion,
    cache_control: { type: 'ephemeral' },
  }],
  messages: mensajes,
};

return [{ json: { peticion, lead_id: lead.id, telefono: lead.telefono } }];

// WhatsApp no es markdown, y un mensaje en frío con enlaces se va a spam.
function limpiar(txt, maxLargo) {
  let t = String(txt || '')
    .replace(/\*\*(.+?)\*\*/g, '$1')     // **negrita**
    .replace(/^[-*•]\s+/gm, '')            // viñetas
    .replace(/^#{1,6}\s+/gm, '')           // títulos
    .replace(/\[(.+?)\]\(.+?\)/g, '$1')  // [texto](url)
    .replace(/\n{3,}/g, '\n\n')
    .replace(/[ \t]+/g, ' ')
    .trim();
  if (t.length > maxLargo) {
    // Cortar en la última frase completa que quepa, no a mitad de palabra.
    const corte = t.slice(0, maxLargo);
    const fin = Math.max(corte.lastIndexOf('. '), corte.lastIndexOf('? '), corte.lastIndexOf('\n'));
    t = (fin > maxLargo * 0.5 ? corte.slice(0, fin + 1) : corte).trim();
  }
  return t;
}

// La respuesta puede traer bloques de razonamiento antes del texto.
function textoDelModelo(respuesta) {
  if (respuesta?.stop_reason === 'refusal') {
    throw new Error('El modelo declinó la petición. Revisa el prompt en ajustes.');
  }
  const bloque = (respuesta?.content || []).find((b) => b.type === 'text' && b.text);
  if (!bloque) {
    throw new Error('Respuesta sin texto: ' + JSON.stringify(respuesta).slice(0, 400));
  }
  return bloque.text;
}


// Literal SQL seguro. Duplicar la comilla simple es lo mismo que hace
// quote_literal() en Postgres, y con standard_conforming_strings=on (por
// defecto) no hay ninguna otra secuencia de escape que valga.
const lit = (v) => (v === null || v === undefined || v === '')
  ? 'null'
  : "'" + String(v).replace(/'/g, "''") + "'";

            const cfg  = $('Contexto').first().json.cfg;
            const lead = $('Contexto').first().json;
            const entrante = $('Normalizar').first().json;
            const d = JSON.parse(textoDelModelo($input.first().json));

            const intencion = d.intencion || 'pregunta';
            const esBaja = intencion === 'baja';

            // En una baja no se improvisa: se manda el texto fijo de ajustes.
            let respuesta = esBaja
              ? (cfg.plantilla_baja || 'Listo, no te escribo más. Que te vaya muy bien.')
              : limpiar(d.respuesta, 700);

            const estado = ({
              baja: 'no_contactar',
              interesado: 'interesado',
              pregunta: 'respondio',
              no_interesado: 'no_interesado',
              no_es_el_indicado: 'no_interesado',
              ruido: 'respondio',
            })[intencion] || 'respondio';

            const temperatura = Math.min(5, Math.max(1, Number(d.temperatura) || 3));
            const avisar = !esBaja && (d.requiere_humano === true || temperatura >= 4);

            const aviso = (cfg.plantilla_aviso || '')
              .replace('{{negocio}}', lead.negocio || '')
              .replace('{{ciudad}}', lead.ciudad || 'sin ciudad')
              .replace('{{telefono}}', lead.telefono || '')
              .replace('{{temperatura}}', String(temperatura))
              .replace('{{mensaje}}', String(entrante.texto).slice(0, 200))
              .replace('{{nota}}', d.nota_interna || '');

            return [{ json: {
              intencion, estado, temperatura, esBaja, avisar, aviso,
              requiere_humano: d.requiere_humano === true,
              responder: respuesta.trim().length > 0,
              respuesta,
              respuesta_sql: lit(respuesta),
              nota_sql: lit(d.nota_interna || ''),
              telefono: lead.telefono,
              telefono_notificaciones: cfg.telefono_notificaciones,
              lead_id: lead.id,
              delay_ms: Math.min(80, Math.max(25, respuesta.length / 3)) * 100,
            } }];
